    "id": "common/TreeShapePatch.d.ts",
    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\n/** 程序化树共享效果的绝对参数补丁；省略字段保持不变。与 Tree Variations 面板共用配方和 Effect 参数，影响所有使用该效果的树，不创建单树覆盖。先读取 TreeAsset.properties.treeShape 再计算相对变化。 */\n\nexport type TreeShapePatch = {\n  /** 整棵树相对基础实例的水平缩放，包含树干、树冠；与 verticalScale 同时调整可整体放大缩小。 取值范围：0.1 到 3。 */\n  horizontalScale?: number;\n  /** 整棵树相对基础实例的高度缩放。 取值范围：0.1 到 3。 */\n  verticalScale?: number;\n  /** 相对基础实例朝向的水平旋转，单位为度。 取值范围：-180 到 180。 */\n  yawDegrees?: number;\n  /** 主树干径向粗细倍率；不移动枝条中心线。 取值范围：1 到 2。 */\n  trunkThicknessScale?: number;\n  /** 树枝长度倍率；小于 1 修剪枝梢，大于 1 延长枝条。 取值范围：0.1 到 3。 */\n  branchLengthScale?: number;\n  /** 每米枝条的弯曲角度。 取值范围：0 到 90。 */\n  branchCurvatureDegreesPerMeter?: number;\n  /** 基础枝条的保留比例，0 到 1；1 为全部保留。 取值范围：0 到 1。 */\n  branchDensity?: number;\n  /** 基础叶片的保留比例，0 到 1；1 已为最大叶量。想更浓密时先读取当前值，不能用树林株数 count 代替。 取值范围：0 到 1。 */\n  leafDensity?: number;\n  /** 单张树叶卡片的大小倍率；不是新增叶片数量。 取值范围：0.1 到 5。 */\n  leafSizeScale?: number;\n  /** 树叶颜色，sRGB 三通道整数 0 到 255。 */\n  leafColorRgb?: [number, number, number];\n  /** 树皮颜色，sRGB 三通道整数 0 到 255。 */\n  barkColorRgb?: [number, number, number];\n};\n",
