    "id": "tools/spatial.check.d.ts",
    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\nimport type { AgentToolsDeclaration } from \"../common/AgentTools\";\ndeclare global {\n  namespace AgentTools {\n    interface SpatialApi {\n      /**\n       * 调用入口：await tools.spatial.check(input)\n       * 一次检查指定坐标的地形条件，逐点返回符合/不符合和原因，不搜索或重选位置。\n       * @param input - 最多 32 个坐标及用户明确要求的地形条件；只检查这些点，不代表完整建筑占地或几何碰撞。\n       * @returns 每个点含 matches、failedConstraints 和 surface。outside_world 表示超出已发布地形范围。条件已判定后停止检查，不自行追加条件反复试探。\n       */\n      check(input: {\n        /** 精确检查的世界坐标，最多 32 个；不会寻找或替换成附近位置。 元素数量：1 到 32。 */\n        positions: Array<{\n            x: number;\n            z: number;\n          }>;\n        /** 基于当前实时地表状态的约束。 */\n        constraints?: {\n          /** 可见表面的最低世界海拔，单位为米；省略时不设下限。 */\n          minimumElevationMetres?: number;\n          /** 可见表面的最高世界海拔，单位为米；省略时不设上限。 */\n          maximumElevationMetres?: number;\n          /** 地表最小坡度，单位为度；省略时不设下限。 最小值：0。 */\n          minimumSlopeDegrees?: number;\n          /** 地表最大坡度，单位为度；省略时不设上限。 最小值：0。 */\n          maximumSlopeDegrees?: number;\n          /** 地表最小湿度值；省略时不设下限。 */\n          minimumMoisture?: number;\n          /** 地表最大湿度值；省略时不设上限。 */\n          maximumMoisture?: number;\n          /** true 只搜索水面，false 只搜索陆地地形；省略时两者都可返回。验证地形高度变化时必须使用 false，水域位置的 elevationMetres 是水面而不是水底。 */\n          water?: boolean;\n          /** 到内陆水体（河道、湖泊、池塘）的最大水平距离，单位为米；不包含海洋；省略时不限制。 最小值：0。 */\n          maximumRiverDistanceMetres?: number;\n          /** 到最近道路的最大水平距离，单位为米；省略时不限制。 最小值：0。 */\n          maximumRoadDistanceMetres?: number;\n        };\n      }): Promise<{\n        items: Array<{\n            position: {\n              x: number;\n              z: number;\n            };\n            matches: boolean;\n            failedConstraints: Array<string>;\n            surface: {\n              /** 当前可见表面高度：water=true 时是水面高度，water=false 时是地形高度；不是水下河床或湖底高度。 */\n              elevationMetres: number;\n              /** 采样点地形坡度，单位为度；不是水面倾角。 */\n              slopeDegrees: number;\n              /** 世界地表湿度场的归一化值（0 到 1），不是农田土壤含水量，也不能据此判断脚下是否有水。 */\n              moisture: number;\n              /** 此采样点是否被水面覆盖；只描述该点，不表示周边没有水体。 */\n              water: boolean;\n              /** 兼容字段：此点到内陆水体（河道、湖泊、池塘）的水平距离，单位为米；不包含海洋，不能解释为最近水面距离。 */\n              riverDistanceMetres: number;\n              /** riverDistanceMetres 的实际测量范围；名称为兼容旧调用保留。 */\n              riverDistanceScope: \"inland-water-excluding-ocean\";\n              /** 未计算到最近全部水体（含海洋、河流、湖泊、池塘）的距离，固定返回 null 表示未知；不是没有水或距离无限，不能用 riverDistanceMetres 代替。 */\n              nearestWaterDistanceMetres: null;\n              /** 此点到最近道路的距离，单位为米。 */\n              roadDistanceMetres: number;\n            } | null;\n          }>;\n      }>;\n    }\n  }\n}\n\nexport {};\n",
