    "id": "tools/spatial.viewer.d.ts",
    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\nimport type { AgentToolsDeclaration } from \"../common/AgentTools\";\ndeclare global {\n  namespace AgentTools {\n    interface SpatialApi {\n      /**\n       * 调用入口：await tools.spatial.viewer(input)\n       * 读取已发布的实时玩家相机位置和朝向，不移动玩家，不使用 viewer 指令参照快照。\n       * @param input - 无参数。传送后验证实际位置，应在传送 execute 提交完成后的下一次 execute 调用。\n       * @returns source=published；回答当前位置和朝向可直接使用 position、headingDegrees、pitchDegrees 和 nearestHorizontalAxis。position 是眼睛的绝对世界坐标，Y 不是离地眼高；本接口不测量脚下海拔、离地高度或地理区位，不能据此推断这些信息。不会返回未提交草稿中的目标位置；需要检查脚下地表时另读 spatial.check 声明。\n       */\n      viewer(input?: Record<string, never>): Promise<{\n        source: \"published\";\n        mode: \"roam\" | \"orbit\";\n        /** 实时相机眼睛的绝对世界坐标 [x,y,z]，单位为米。Y 是相对世界原点的高度，不是相机离地眼高，也不是脚下地面海拔；坐标本身不提供东南西北地理区位。 */\n        position: [number, number, number];\n        /** 实时相机朝向向量。 */\n        forward: [number, number, number];\n        /** 由同一 forward 换算的水平航向角：[0,360)，0=-Z、90=+X、180=+Z、270=-X。水平分量长度≤1e-8 时为 null，方向未定义。 */\n        headingDegrees: number | null;\n        /** 由同一 forward 换算的俯仰角：正数朝上、负数朝下、0 水平；向量长度≤1e-8 时为 null。 */\n        pitchDegrees: number | null;\n        /** 当前水平朝向最接近的世界轴向，供文字说明方向；不是精确朝向或地图方位名称。X/Z 分量绝对值相等时取 X；水平分量长度≤1e-8 时为 null。 */\n        nearestHorizontalAxis: (\"+X\" | \"-X\" | \"+Z\" | \"-Z\") | null;\n      }>;\n    }\n  }\n}\n\nexport {};\n",
    "imports": [
      "common/AgentTools.d.ts"
    ],
