    "id": "tools/water.digRiver.d.ts",
    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\nimport type { AgentToolsDeclaration } from \"../common/AgentTools\";\ndeclare global {\n  namespace AgentTools {\n    interface WaterApi {\n      /**\n       * 调用入口：await tools.water.digRiver(input)\n       * 在玩家面前挖河或溪流，在一次项目编辑中一起创建河床和原生河流水面。\n       * @param input - 直接调用一次。未指定距离时优先玩家正前方 20 米，自动绕开现成水体。用户未提供尺寸或距离时传 {}。\n       * @returns 返回河流标识和中心线。以外层 execute 提交及运行回执确认发布。\n       */\n      digRiver(input: {\n        /** 河道两端连线中点到玩家的距离，默认 20 米。 取值范围：5 到 150。 */\n        distanceMetres?: number;\n        /** 河道横向跨度，默认 32 米。 取值范围：8 到 100。 */\n        lengthMetres?: number;\n        /** 河道宽度，默认 6 米。 取值范围：1 到 16。 */\n        widthMetres?: number;\n        /** 河道深度，默认 0.8 米。 取值范围：0.25 到 3。 */\n        depthMetres?: number;\n      }): Promise<{\n        id: string;\n        centerline: Array<{\n            x: number;\n            z: number;\n          }>;\n      }>;\n    }\n  }\n}\n\nexport {};\n",
