    "id": "tools/atmosphere.update.d.ts",
    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\nimport type { AgentToolsDeclaration } from \"../common/AgentTools\";\nimport type { EnvironmentUpdateResult } from \"../common/EnvironmentUpdateResult\";\ndeclare global {\n  namespace AgentTools {\n    interface AtmosphereApi {\n      /**\n       * 调用入口：await tools.atmosphere.update(input)\n       * 修改天空颜色或一个或多个天象通道。\n       * @param input - 天空改色使用 atmosphere.skyColorRgb，null 恢复默认；无需修改时间、云雾或天气预设。至少包含一个天象字段；预设先应用，显式通道随后覆盖。天空颜色也参与环境光烘焙。\n       * @returns 规范化请求和草稿目标状态。execute 提交后才激活天象与环境光过渡；运行失败记录在 execute.receipt.runtimeErrors，不撤销已提交的编辑数据。\n       */\n      update(input: {\n        weatherPreset?: \"clear\" | \"cloudy\" | \"rain\" | \"storm\" | \"snow\" | \"fog\";\n        /** 风通道局部修改。 */\n        wind?: {\n          /** 持续风速，单位为米每秒。 取值范围：0 到 60。 */\n          speedMetresPerSecond?: number;\n          /** 风吹向的世界水平航向，度：0 为 -Z，90 为 +X，-90 为 -X；不是风的来向或内部偏转角。过渡完成后生效；不修改基础风向。 取值范围：-180 到 180。 */\n          directionDegrees?: number;\n          /** 阵风强度。 取值范围：0 到 1。 */\n          gustiness?: number;\n          /** 乱流程度。 取值范围：0 到 1。 */\n          turbulence?: number;\n        };\n        /** 降水通道局部修改。 */\n        precipitation?: {\n          /** 降雨强度。 取值范围：0 到 1。 */\n          rainIntensity?: number;\n          /** 降雪强度。 取值范围：0 到 1。 */\n          snowIntensity?: number;\n        };\n        /** 天空颜色与云雾通道局部修改。 */\n        atmosphere?: {\n          /** 天空染色的 sRGB 三通道整数 0 到 255；例如紫色 [180,80,255]，null 恢复默认昼夜天空。染色立即生效并保持到当前世界销毁或显式恢复；保留时间、天气与太阳/月亮，实际亮度受昼夜光照影响。 */\n          skyColorRgb?: [number, number, number] | null;\n          /** 云层覆盖。 取值范围：0 到 1。 */\n          cloudiness?: number;\n          /** 雾强度。 取值范围：0 到 1。 */\n          fogIntensity?: number;\n        };\n        /** 闪电通道局部修改。 */\n        lightning?: {\n          /** 闪电频率。 取值范围：0 到 1。 */\n          frequency?: number;\n          /** 闪电强度。 取值范围：0 到 1。 */\n          intensity?: number;\n        };\n        /** 天气通道过渡秒数，省略时为 1；天空染色立即生效。 取值范围：0 到 60。 */\n        transitionDuration?: number;\n        /** 是否等待环境光烘焙发布，省略时为 true。 */\n        waitForIbl?: boolean;\n      }): Promise<EnvironmentUpdateResult>;\n    }\n  }\n}\n\nexport {};\n",
