    "id": "tools/terrain.inspect.d.ts",
    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\nimport type { AgentToolsDeclaration } from \"../common/AgentTools\";\nimport type { TerrainAssetKind } from \"../common/TerrainAssetKind\";\nimport type { Ref } from \"../common/Ref\";\ndeclare global {\n  namespace AgentTools {\n    interface TerrainApi {\n      /**\n       * 调用入口：await tools.terrain.inspect(input)\n       * 读取一个稳定地形或岩石资产引用的详细状态和属性。\n       * @param input - 来自 terrain.query 或 terrain.create/update 的 Ref；类型专属字段见 skills/terrain/references/asset-types.md。\n       * @returns 直接返回与 ref.kind 对应的具体地形或岩石资产，类型专属字段位于 result.properties；不存在 item 包装层。\n       */\n      inspect<T extends TerrainAssetKind & keyof AssetDetailsByType>(\n        input: { ref: Ref & { kind: T } }\n      ): Promise<AssetDetailsByType[T]>;\n    }\n  }\n}\nexport {};\n",
