    "id": "tools/terrain.patch.d.ts",
    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\nimport type { AgentToolsDeclaration } from \"../common/AgentTools\";\nimport type { ImpactBudget } from \"../common/ImpactBudget\";\nimport type { MutationResult } from \"../common/MutationResult\";\nimport type { Target } from \"../common/Target\";\ndeclare global {\n  namespace AgentTools {\n    interface TerrainApi {\n      /**\n       * 调用入口：await tools.terrain.patch(input)\n       * 抬高或降低现有局部地势，不创建独立世界资产。\n       * @param input - 操作方向、空间目标、范围、改变量和可选执行控制。\n       * @returns 成功时返回 applied/preview 状态、地形修改计数、范围和事务标识；执行失败通过 Tool Error 返回。\n       */\n      patch(input: {\n        /** raise 抬高现有地势，lower 降低现有地势。 */\n        operation: \"raise\" | \"lower\";\n        /** 局部高度笔刷中心的空间目标；不会创建持久地貌资产。 */\n        target: Target;\n        /** 平滑笔刷的外半径；中心一半范围应用完整高度差。实际最小值由当前高度场分辨率决定，省略时使用可表达的最小半径。 取值范围：0.5 到 500。 */\n        radiusMetres?: number;\n        amount: ({\n          /** 语义高度幅度：subtle=1.5 米、moderate=4 米、strong=10 米。 */\n          intensity: \"subtle\" | \"moderate\" | \"strong\";\n        }) | {\n          /** 笔刷中心完整应用的垂直高度差，单位为米；raise 使用正幅值，lower 由 operation 转为负方向。 取值范围：0.1 到 200。 */\n          heightDeltaMetres: number;\n        };\n        /** 高度从中心向边缘平滑衰减；当前只支持 smooth，省略时同样使用 smooth。 */\n        falloff?: \"smooth\";\n        /** 默认 apply；preview 只返回影响估算。 */\n        executionMode?: \"apply\" | \"preview\";\n        impactBudget?: ImpactBudget;\n      }): Promise<MutationResult>;\n    }\n  }\n}\n\nexport {};\n",
