    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\nimport type { AgentToolsDeclaration } from \"../common/AgentTools\";\ndeclare global {\n  namespace AgentTools {\n    interface VegetationApi { readonly materials: VegetationMaterialsApi; }\n    interface VegetationMaterialsApi {\n      /**\n       * 调用入口：await tools.vegetation.materials.inspect(input)\n       * 读取全部公开世界级植被材质的原生部位/生态层分组、槽数、当前线性 RGB 参数范围与事务版本。filter 各维度取交集，同一维度取并集。颜色范围包含作者继承与原生槽默认值；未覆盖的草材质实际跟随 grassAppearance。返回参数不代表最终像素。\n       * @param input - 可按真实 parts、layers、assetIds 限定；省略 filter 表示全部公开世界级植被材质。\n       * @returns 完整分组摘要与当前事务版本；不改作者参数或植被分布。\n       */\n      inspect(input?: {\n        filter?: {\n          /** 最少 1 个元素。 */\n          parts?: Array<string>;\n          /** 最少 1 个元素。 */\n          layers?: Array<string>;\n          /** 最少 1 个元素。 */\n          assetIds?: Array<string>;\n        };\n      }): Promise<{\n        scope: \"shared-materials\";\n        instanceSelectionSupported: false;\n        /** 这些素材的所有实例和LOD共用修改；不是当前画面实例集合。 */\n        affectedAssetIds: Array<string>;\n        versionToken: string;\n        matchedSlotCount: number;\n        groups: Array<{\n            part: string;\n            layers: Array<string>;\n            slotCount: number;\n            /** 生态层在原生种植配方中的名称，与 layers 的稳定标识逐项对应。 */\n            layerNames: Array<string>;\n            parameterColorRange: {\n              min: [number, number, number];\n              max: [number, number, number];\n            };\n            authoredChannelCount: number;\n          }>;\n      }>;\n    }\n  }\n}\n\nexport {};\n",
