    "id": "tools/animals.query.d.ts",
    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\nimport type { AgentToolsDeclaration } from \"../common/AgentTools\";\ndeclare global {\n  namespace AgentTools {\n    interface AnimalsApi {\n      /**\n       * 调用入口：await tools.animals.query(input)\n       * 分页查询当前动物实例，包括尚未加载模型的规划身份；可按 typeId 和 visible 筛选。只读，不触发模型下载。enabled=false 表示动物系统关闭并返回空列表；loaded=false 表示模型资源尚未就绪，不能立即执行显式行为命令；不代表逻辑模拟停止。远处动物可在 coarse 模式移动和响应事件，visible 只说明渲染可见性。数量、激活距离和分布配置通过 animals.config.get/update 修改。\n       * @param input - 使用返回的真实 id、typeId；省略筛选查询全部。offset 默认 0，limit 默认 50，最大 100。\n       * @returns 当前启用状态、动物身份、米制世界位置、加载与显示状态。viewerRelation直接给出本次动物位置相对玩家的方向；动物自主移动后须重新查询。matchedCount 为全部匹配数，nextOffset 缺省表示读完。\n       */\n      query(input: {\n        /** 非空稳定标识，不含控制字符，UTF-8 最多 128 字节。 字符长度：1 到 128。 */\n        typeId?: string;\n        visible?: boolean;\n        /** 最小值：0。 */\n        offset?: number;\n        /** 取值范围：1 到 100。 */\n        limit?: number;\n      }): Promise<{\n        enabled: boolean;\n        /** 仅本页统计；不是全部 matchedCount 的加载状态。renderActive 不证明当前相机画面可见。 */\n        pageSummary: {\n          scope: \"returned-page\";\n          returnedCount: number;\n          loadedCount: number;\n          renderActiveCount: number;\n        };\n        items: Array<{\n            /** 非空稳定标识，不含控制字符，UTF-8 最多 128 字节。 */\n            id: string;\n            /** 非空稳定标识，不含控制字符，UTF-8 最多 128 字节。 */\n            typeId: string;\n            /** 物种身份；多个模型 typeId 可以属于同一物种。 */\n            speciesId: string;\n            label: string;\n            /** 模型资源是否已加载；false 不代表没有移动或逻辑活动。 */\n            loaded: boolean;\n            /** 模型当前是否显示；隐藏动物仍可参与粗粒度模拟。 */\n            visible: boolean;\n            position: [number, number, number];\n            /** 相对玩家的水平位置事实：任务中使用提交指令时的视角，任务外用实时视角。forwardMetres正值在前，rightMetres正值在右；direction为八方位扇区，不是世界东西南北。 */\n            viewerRelation?: {\n              basis: \"instruction-viewer\" | \"live-viewer\";\n              forwardMetres: number;\n              rightMetres: number;\n              direction: \"here\" | \"front\" | \"front-right\" | \"right\" | \"behind-right\" | \"behind\" | \"behind-left\" | \"left\" | \"front-left\";\n            };\n          }>;\n        matchedCount: number;\n        offset: number;\n        nextOffset?: number;\n      }>;\n    }\n  }\n}\n\nexport {};\n",
